update public.learning_paths
set
  title = 'Public Policy Analysis',
  goal = 'Public Policy Analysis',
  summary = 'This course teaches students to analyze public problems and develop actionable policy recommendations. Students learn the policy process, problem definition, evidence assessment, stakeholder analysis, policy instruments, economics, cost-benefit analysis, equity analysis, implementation, evaluation, major policy domains, and professional policy memo communication.',
  data = $ppoljson${"slug": "public-policy-analysis", "title": "Public Policy Analysis", "description": "This course teaches students to analyze public problems and develop actionable policy recommendations. Students learn the policy process, problem definition, evidence assessment, stakeholder analysis, policy instruments, economics, cost-benefit analysis, equity analysis, implementation, evaluation, major policy domains, and professional policy memo communication.", "topics": [{"id": "b6043d1a-553d-4f80-a193-1c9404ce932e", "type": "topic", "title": "Public problems, policy systems, and the craft of policy analysis", "description": "Understand policy analysis as practical, ethical problem solving in complex public systems.", "children": [{"id": "e2bf8a3e-ef31-4d1d-9d00-bc3870c84b47", "type": "subtopic", "title": "Public problems and public value", "children": [{"id": "b70ec831-c71a-40e2-8710-cceec36216ef", "type": "concept", "title": "Public goods, externalities, collective action, rights, and harms"}, {"id": "342ef057-ed4c-42a6-af47-785cf5cb9584", "type": "concept", "title": "Public value, legitimacy, accountability, and trust"}, {"id": "57e748a6-2cbd-4f3e-b0cf-3c078b376ede", "type": "concept", "title": "Problem complexity, uncertainty, and competing values"}], "description": "Students learn that policy analysis starts by asking what is public about the problem and what value government action should create."}, {"id": "2b094674-dacb-4722-9a3a-5e285e2b78a4", "type": "subtopic", "title": "Policy analysis as craft", "children": [{"id": "305d8cf2-1d3c-4d0f-b505-1e67ad71d06b", "type": "concept", "title": "Analyst roles and professional norms"}, {"id": "2466e118-2a32-4964-8c3f-8931e26c1074", "type": "concept", "title": "Evidence, ethics, politics, and practicality"}, {"id": "12ad8e9f-67be-4352-8ae7-f88a31c5f991", "type": "concept", "title": "Client, public, and community accountability"}], "description": "This subtopic frames analysis as disciplined judgment, not a formula."}, {"id": "c163314d-6b3c-4157-81f1-122141cef33c", "type": "subtopic", "title": "Policy systems thinking", "children": [{"id": "996ae165-db41-4359-8998-cc06b8e7d6c2", "type": "concept", "title": "Systems, incentives, institutions, and behavior"}, {"id": "4ef0e79e-d6fe-43b2-844e-f89a2c55b7b2", "type": "concept", "title": "Feedback loops and implementation environments"}, {"id": "4ac5fc9e-8b57-40fa-a324-00825c225878", "type": "concept", "title": "Unintended consequences and adaptive learning"}], "description": "Students learn to see policies as interventions inside systems with feedback and unintended effects."}]}, {"id": "0bdcf59d-027b-4286-891d-af7085aac03d", "type": "topic", "title": "Policy process, agenda setting, institutions, and political context", "description": "Analyze how problems reach government agendas and move through institutions, coalitions, and constraints.", "children": [{"id": "f307c498-d623-4c6e-a4e2-110294652fe4", "type": "subtopic", "title": "Policy cycle and process models", "children": [{"id": "a555cf4f-2312-413b-addc-aa4429ebc18c", "type": "concept", "title": "Agenda setting, formulation, adoption, implementation, evaluation"}, {"id": "8ec05e83-174f-45e2-a837-438e8adce240", "type": "concept", "title": "Multiple streams, advocacy coalitions, and punctuated equilibrium"}, {"id": "0289639f-4556-43b8-8ee3-ee1e99c855e4", "type": "concept", "title": "Policy windows and timing"}], "description": "Students learn the classic stages model and why real policy work is less linear."}, {"id": "8fbac1f4-db88-4bae-820a-5292a305a5de", "type": "subtopic", "title": "Institutions and decision venues", "children": [{"id": "1d40f074-520d-4005-b7c5-5a9ad01f2cd5", "type": "concept", "title": "Legislatures, executives, courts, agencies, federalism, and local governments"}, {"id": "e488bddb-767b-451b-b27b-33ba69d40bbe", "type": "concept", "title": "Administrative procedures and rulemaking"}, {"id": "978082c9-7673-4d9f-87bf-1d663e43101c", "type": "concept", "title": "Intergovernmental and cross-sector governance"}], "description": "This subtopic shows how formal rules and venues shape what is possible."}, {"id": "92998385-ad96-48de-b31f-c98be26ac6fc", "type": "subtopic", "title": "Political feasibility", "children": [{"id": "17dab88b-e2e9-454b-995b-81ca35046e93", "type": "concept", "title": "Veto points and policy entrepreneurs"}, {"id": "527e4d45-34de-4045-9ad8-a220c05c64a3", "type": "concept", "title": "Parties, interest groups, media, and public opinion"}, {"id": "cae72462-35b8-456d-a67b-2a636ea36be4", "type": "concept", "title": "Risk, timing, and coalition strategy"}], "description": "Students learn to analyze power, incentives, coalitions, and opposition."}]}, {"id": "4f630565-f697-4ab5-b03d-1b79fdcbc649", "type": "topic", "title": "Problem definition, evidence needs, and policy framing", "description": "Define the problem precisely, identify evidence gaps, and frame choices without smuggling in conclusions.", "children": [{"id": "920136de-c2ca-4ae2-afd3-d92d2214f6f9", "type": "subtopic", "title": "Problem definition", "children": [{"id": "358f4a1f-ba67-4100-a95f-6ad758ecb3ee", "type": "concept", "title": "Problem statements and scope"}, {"id": "63d324c4-f1fe-4607-8f6a-52be1275afaa", "type": "concept", "title": "Root causes and causal diagrams"}, {"id": "d4e216f4-42cf-4c16-af04-933f3ef4123d", "type": "concept", "title": "Baseline, trend, magnitude, and affected populations"}], "description": "Students learn to define problems in actionable terms without confusing symptoms, causes, and solutions."}, {"id": "1b457a1a-2248-4968-ad21-356384e1a70b", "type": "subtopic", "title": "Evidence needs", "children": [{"id": "e5ecc8f3-adf9-4355-b851-f44fb6931259", "type": "concept", "title": "Descriptive, causal, implementation, cost, and equity evidence"}, {"id": "2262ca4d-d973-4ad2-8320-7a485fc32066", "type": "concept", "title": "Evidence quality and uncertainty"}, {"id": "abb1bb4d-b0e4-4ecd-8c67-44f91168b803", "type": "concept", "title": "Evidence gaps and assumptions"}], "description": "This subtopic teaches students to ask what evidence is needed before gathering everything."}, {"id": "6e9a1142-ad64-4ed1-8313-3c9568c512e8", "type": "subtopic", "title": "Framing and narratives", "children": [{"id": "ba65ed1c-e5b8-4365-9953-67a96f9a5e91", "type": "concept", "title": "Diagnostic, prognostic, and motivational frames"}, {"id": "c6432235-1b8c-4778-9c59-a8ca46012af2", "type": "concept", "title": "Values, language, and problem ownership"}, {"id": "b0070e5e-0c49-431e-859b-a5ae6ee1f3f8", "type": "concept", "title": "Avoiding biased or manipulative framing"}], "description": "Students learn that policy frames shape attention, legitimacy, and feasible solutions."}]}, {"id": "72f7c512-6a33-417f-b9be-5f4c6cdd7355", "type": "topic", "title": "Stakeholder analysis, public engagement, and power mapping", "description": "Identify affected communities, decision-makers, implementers, opponents, and forms of public voice.", "children": [{"id": "ef31e78f-5112-43aa-b1fd-44d0d4921a17", "type": "subtopic", "title": "Stakeholder identification", "children": [{"id": "2cd56036-e4a2-4dc5-865e-eea1ea8e6237", "type": "concept", "title": "Beneficiaries, burdened groups, agencies, providers, advocates, opponents"}, {"id": "893857a2-1f3d-43dd-a103-5ec9352dfaeb", "type": "concept", "title": "Direct and indirect stakeholders"}, {"id": "f8999f2b-4dc6-4703-a387-b9b9b9f35f94", "type": "concept", "title": "Affected communities and lived experience"}], "description": "Students learn to identify who affects, is affected by, implements, funds, or can block a policy."}, {"id": "4ff0fbfa-1cf4-4966-9ad0-d4755615486e", "type": "subtopic", "title": "Power and interest mapping", "children": [{"id": "5f4500a9-5c3f-4528-bfcd-f59857e94199", "type": "concept", "title": "Power-interest grids"}, {"id": "bd1289a5-955a-4c7d-953c-dad15b55c294", "type": "concept", "title": "Coalition mapping"}, {"id": "992d5d4a-77ae-401e-a166-1e3a98d9b8b9", "type": "concept", "title": "Incentives, constraints, and negotiation positions"}], "description": "This subtopic helps students anticipate support, resistance, and implementation realities."}, {"id": "72a7cb47-d0f7-40d6-8ffc-d4e3a7a01b41", "type": "subtopic", "title": "Public engagement", "children": [{"id": "1f6dcaad-6d42-45e4-9579-e1b71f62ac43", "type": "concept", "title": "Participation methods"}, {"id": "b24db7cf-118f-4054-8cd9-e3d9da40d583", "type": "concept", "title": "Representative voice and inclusion"}, {"id": "d671ac96-8010-452d-a5e1-9bccec3bc49c", "type": "concept", "title": "Feedback loops and accountability"}], "description": "Students learn to distinguish meaningful engagement from symbolic consultation."}]}, {"id": "c6d52457-f1d0-46bf-af67-3e7949f30bf9", "type": "topic", "title": "Policy alternatives, instruments, and design choices", "description": "Develop feasible policy options and match instruments to goals, behaviors, institutions, and risks.", "children": [{"id": "1b9c2dc5-6d75-41f6-aba2-c8c09212637a", "type": "subtopic", "title": "Generating alternatives", "children": [{"id": "df418b90-6b88-470a-98d5-88c790b0eb24", "type": "concept", "title": "Status quo, incremental, structural, and pilot options"}, {"id": "c1c06b17-a923-43b9-a91e-8c870383b62f", "type": "concept", "title": "Benchmarks and comparative policy learning"}, {"id": "7b4202b4-bd2f-4f71-ae4a-34b5944a0d08", "type": "concept", "title": "Screening weak alternatives"}], "description": "Students learn to develop options that are actually distinct, feasible, and responsive to the problem."}, {"id": "85a4f56f-cbcf-40fc-b530-fe68a88e7ae2", "type": "subtopic", "title": "Policy instruments", "children": [{"id": "d91efe8a-1d8d-48cf-95ca-9f9f0c5b52e5", "type": "concept", "title": "Regulation, taxes, subsidies, public provision, information, nudges, mandates"}, {"id": "287c29f9-8527-4b22-8ae9-c87889da2f70", "type": "concept", "title": "Market-based instruments and public-private partnerships"}, {"id": "2845fa4a-63dd-4970-a86c-9806f8b3059f", "type": "concept", "title": "Administrative simplification and service design"}], "description": "This subtopic covers the tools governments use to change behavior or allocate resources."}, {"id": "d522221c-27fc-468b-9672-dd88e8332d5b", "type": "subtopic", "title": "Criteria and tradeoffs", "children": [{"id": "446f1bae-6eb3-44af-a0bf-79d7c0ee82b6", "type": "concept", "title": "Effectiveness, efficiency, equity, feasibility, legality, sustainability"}, {"id": "f6cbf03a-83f9-41aa-8e7d-dfef80c6f9c0", "type": "concept", "title": "Weighted criteria and decision matrices"}, {"id": "0fe27933-fa11-495d-93b3-0b843bb28cbd", "type": "concept", "title": "Tradeoffs and robustness"}], "description": "Students learn to judge alternatives transparently."}]}, {"id": "65d88136-12dd-449a-ba53-ccaf9724ecda", "type": "topic", "title": "Economic rationale, market failure, public finance, and budget context", "description": "Use economic and fiscal reasoning to understand when government intervention is justified and affordable.", "children": [{"id": "bcac6dcf-4cdf-4a50-8c1c-0bb30893d421", "type": "subtopic", "title": "Economic rationale for intervention", "children": [{"id": "87a42c59-6a43-4a7d-9aba-ee14cd72bb20", "type": "concept", "title": "Externalities, public goods, information asymmetry, market power"}, {"id": "a02ee548-319d-4a90-abc9-8fdf5a872b04", "type": "concept", "title": "Behavioral failures and coordination problems"}, {"id": "0e045a0a-86b2-4147-a79d-8cd9fd07ed60", "type": "concept", "title": "Government failure and limits of intervention"}], "description": "Students learn when markets, institutions, or private action may fail to produce acceptable outcomes."}, {"id": "42306e04-2514-4dfe-8eb9-22f12f9ce50b", "type": "subtopic", "title": "Public finance basics", "children": [{"id": "817fee10-b231-4aa3-82f4-bf71eb3d5c16", "type": "concept", "title": "Revenue, expenditures, deficits, debt, and fiscal sustainability"}, {"id": "dbaa71da-45ed-4fcf-b678-4c48130ab0d4", "type": "concept", "title": "Tax incidence, progressivity, and efficiency"}, {"id": "d2bf1050-27b7-411e-91a4-51f4b427dc64", "type": "concept", "title": "Budget rules and fiscal institutions"}], "description": "This subtopic connects policy choices to taxation, spending, and fiscal constraints."}, {"id": "cf434734-7cc4-4ba7-89f4-bab261afa385", "type": "subtopic", "title": "Distribution and incentives", "children": [{"id": "07730a18-54db-4f7c-b421-ab690359ac6a", "type": "concept", "title": "Transfers, benefits, mandates, and tax expenditures"}, {"id": "72abeb10-3d1e-46f9-85ee-9bfe689bc93b", "type": "concept", "title": "Intergovernmental grants and fiscal federalism"}, {"id": "ba506c6f-2a90-4391-ab4b-617ac72fbb77", "type": "concept", "title": "Redistribution and work/savings/investment incentives"}], "description": "Students learn how money flows shape behavior and burden."}]}, {"id": "ad5e607b-4ae3-4bb1-acc5-24d10078a936", "type": "topic", "title": "Decision analysis, cost-benefit, cost-effectiveness, and uncertainty", "description": "Compare alternatives using structured criteria, valuation, sensitivity analysis, and uncertainty displays.", "children": [{"id": "07dc7439-3fa3-4462-8a00-ee87959c49d3", "type": "subtopic", "title": "Structured decision analysis", "children": [{"id": "0299a66c-1d8a-4e71-8cc9-b3415d5797a2", "type": "concept", "title": "Decision trees and alternatives"}, {"id": "b99a94d6-2212-4039-b3ae-16070714d16d", "type": "concept", "title": "Risks, probabilities, and expected values"}, {"id": "eb1fa27d-d22e-4904-8a68-c0be0f96b657", "type": "concept", "title": "Scenario planning and robustness"}], "description": "Students learn to compare alternatives systematically under uncertainty."}, {"id": "27f516db-153c-421c-84d0-2dfa8bf24e8c", "type": "subtopic", "title": "Cost-benefit and cost-effectiveness", "children": [{"id": "c316161d-170d-476a-8a6c-e02ab2686f49", "type": "concept", "title": "Discounting and present value"}, {"id": "5f9c4d47-ffbc-4b4b-9472-7118f4240929", "type": "concept", "title": "Valuing nonmarket impacts"}, {"id": "c38a8aa3-c020-4efd-86ec-9764e269f398", "type": "concept", "title": "Cost-effectiveness versus cost-benefit analysis"}], "description": "This subtopic teaches disciplined comparison of costs, benefits, and outcomes."}, {"id": "ce1968e8-b6ff-40e9-9309-d6b7afa39743", "type": "subtopic", "title": "Sensitivity and uncertainty communication", "children": [{"id": "22a53c69-84b3-4012-9092-cd47490c3c20", "type": "concept", "title": "Sensitivity analysis"}, {"id": "a79c66bc-3f93-4131-81a6-9bd292616dad", "type": "concept", "title": "Distributional weighting and equity considerations"}, {"id": "a267125f-8723-4311-9a3e-f4230a492315", "type": "concept", "title": "Uncertainty displays and decision-maker briefings"}], "description": "Students learn to avoid false precision and show what matters most."}]}, {"id": "b1a20aad-5dca-4aff-aa47-318367c1205a", "type": "topic", "title": "Equity, ethics, race, distributional impact, and public value", "description": "Assess who benefits, who bears costs, and whether a policy advances justice, legitimacy, and public value.", "children": [{"id": "63cc046f-b97e-4a03-810b-1b416a9c3ea0", "type": "subtopic", "title": "Equity analysis", "children": [{"id": "b2a71446-5518-4ca5-99a0-cf6523f5f1d9", "type": "concept", "title": "Distribution by race, income, geography, disability, gender, and age"}, {"id": "cbc83b3c-ed61-4987-8c0b-a9e75853a4ba", "type": "concept", "title": "Procedural, distributive, and recognitional equity"}, {"id": "3963570b-a864-498e-ac74-f7ae663251ef", "type": "concept", "title": "Equity impact analysis"}], "description": "Students learn to assess differential impacts, not just average effects."}, {"id": "b1307363-f299-45bd-85e8-4cc618ee8927", "type": "subtopic", "title": "Ethics and public value", "children": [{"id": "e2d9eb0b-59c4-4ed7-a57f-18390bd8fa35", "type": "concept", "title": "Rights, duties, utility, justice, and care 